(function(){
  'use strict';
  var KEY='welog-pair-sheet-v4';
  var XKEY='welog-padding-x-v1',YKEY='welog-padding-y-v1';
  var controls=document.getElementById('controls'),sheet=document.getElementById('sheet');
  var previewBtn=document.getElementById('previewBtn'),saveBtn=document.getElementById('printBtn');
  function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){return{}}}
  function fontKey(v){if(/^KoPub Batang/.test(v||''))return'batang';if(/^KoPub Dotum/.test(v||''))return'dotum';if(v==='Noto Sans KR')return'noto';if(v==='__system__')return'system';return'pretendard'}
  function syncFont(){var s=read(),sel=controls&&controls.querySelector('select[data-path="font"]'),v=(sel&&sel.value)||s.font||'Pretendard';document.documentElement.dataset.welogFinalFont=fontKey(v)}
  function forceFontState(v){var s=read();s.font=v;try{localStorage.setItem(KEY,JSON.stringify(s))}catch(e){}syncFont()}

  function readNum(k,def){var n=Number(localStorage.getItem(k));return isFinite(n)?n:def}
  function applySpacing(){var x=Math.max(0,Math.min(180,readNum(XKEY,40))),y=Math.max(0,Math.min(180,readNum(YKEY,40)));document.documentElement.style.setProperty('--welog-pad-x',x+'px');document.documentElement.style.setProperty('--welog-pad-y',y+'px')}
  function spacingBox(){if(!controls)return;var anchor=controls.querySelector('.layout-ratio-controls');if(!anchor)return;var old=controls.querySelector('.welog-spacing-control');if(!old){old=document.createElement('section');old.className='welog-spacing-control';old.innerHTML='<div class="welog-control-head"><b>카드 여백</b><span>좌우와 상하 여백을 따로 조절합니다.</span></div><label class="welog-slider-row"><span>좌우</span><input type="range" min="0" max="180" step="5" data-pad-x><b data-pad-x-v></b></label><label class="welog-slider-row"><span>상하</span><input type="range" min="0" max="180" step="5" data-pad-y><b data-pad-y-v></b></label>';anchor.insertAdjacentElement('afterend',old)}var x=readNum(XKEY,40),y=readNum(YKEY,40);old.querySelector('[data-pad-x]').value=x;old.querySelector('[data-pad-y]').value=y;old.querySelector('[data-pad-x-v]').textContent=x+'px';old.querySelector('[data-pad-y-v]').textContent=y+'px';applySpacing()}

  function moveCommission(){if(!sheet)return;var block=sheet.querySelector('.profile.right .commission-block');var footer=sheet.querySelector('.sheet-commission-footer');if(!block){if(footer&&!footer.children.length)footer.remove();return}if(!footer){footer=document.createElement('div');footer.className='sheet-commission-footer';sheet.appendChild(footer)}footer.appendChild(block)}
  function centerParts(){if(!sheet)return;['.profile.left','.center','.profile.right'].forEach(function(q){var el=sheet.querySelector(q);if(el){el.style.transformOrigin='top center';el.style.justifySelf='center'}})}
  function postRender(){syncFont();applySpacing();moveCommission();centerParts()}

  function buildClone(){postRender();var c=sheet.cloneNode(true);c.id='sheet';c.classList.add('welog-exact-preview-sheet');c.style.transform='none';c.style.transformOrigin='top center';c.style.margin='0';return c}
  function ensurePreview(){var m=document.querySelector('.welog-exact-preview');if(m)return m;m=document.createElement('div');m.className='welog-exact-preview';m.hidden=true;m.innerHTML='<button class="welog-exact-preview-backdrop" type="button"></button><section class="welog-exact-preview-dialog"><div class="welog-exact-preview-head"><div><small>PREVIEW</small><b>저장 미리보기</b></div><button type="button" data-exact-close>×</button></div><div class="welog-exact-preview-viewport"><div class="welog-exact-preview-holder"></div></div></section>';document.body.appendChild(m);m.querySelector('.welog-exact-preview-backdrop').onclick=function(){m.hidden=true};m.querySelector('[data-exact-close]').onclick=function(){m.hidden=true};return m}
  function openPreview(){var m=ensurePreview(),holder=m.querySelector('.welog-exact-preview-holder'),vp=m.querySelector('.welog-exact-preview-viewport');holder.innerHTML='';var c=buildClone();holder.appendChild(c);m.hidden=false;requestAnimationFrame(function(){var w=c.offsetWidth,h=c.offsetHeight,maxW=Math.max(200,vp.clientWidth-48),maxH=Math.max(200,vp.clientHeight-48),scale=Math.min(1,maxW/w,maxH/h);c.style.transform='scale('+scale+')';c.style.transformOrigin='top left';holder.style.width=(w*scale)+'px';holder.style.height=(h*scale)+'px'})}
  async function exportExact(){if(!window.html2canvas||!sheet)return;saveBtn.disabled=true;saveBtn.textContent='저장 중…';var host=document.createElement('div');host.className='welog-export-host';var c=buildClone();host.appendChild(c);document.body.appendChild(host);try{if(document.fonts&&document.fonts.ready)await document.fonts.ready;await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var canvas=await html2canvas(c,{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#fff',logging:false,imageTimeout:15000});var a=document.createElement('a');a.download=((read().pairName||'WeLog').trim()||'WeLog')+'.png';a.href=canvas.toDataURL('image/png');document.body.appendChild(a);a.click();a.remove()}catch(e){console.error(e);alert('PNG 저장에 실패했습니다.')}finally{host.remove();saveBtn.disabled=false;saveBtn.textContent='↓ PNG 저장'}}

  if(controls){controls.addEventListener('input',function(e){if(e.target.matches('select[data-path="font"]')){forceFontState(e.target.value);setTimeout(syncFont,0)}if(e.target.matches('[data-pad-x]')){localStorage.setItem(XKEY,e.target.value);var b=e.target.closest('.welog-spacing-control');if(b)b.querySelector('[data-pad-x-v]').textContent=e.target.value+'px';applySpacing()}if(e.target.matches('[data-pad-y]')){localStorage.setItem(YKEY,e.target.value);var b2=e.target.closest('.welog-spacing-control');if(b2)b2.querySelector('[data-pad-y-v]').textContent=e.target.value+'px';applySpacing()}},true);controls.addEventListener('change',function(e){if(e.target.matches('select[data-path="font"]'))forceFontState(e.target.value)},true)}
  if(previewBtn)previewBtn.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();openPreview()},true);
  if(saveBtn)saveBtn.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();exportExact()},true);
  var p=false;function schedule(){if(p)return;p=true;setTimeout(function(){p=false;spacingBox();postRender()},0)}
  if(controls)new MutationObserver(schedule).observe(controls,{childList:true,subtree:false});
  if(sheet)new MutationObserver(schedule).observe(sheet,{childList:true,subtree:false});
  window.addEventListener('resize',postRender);spacingBox();postRender();
})();
